// CSD_PROOF_SKETCH_BEGIN
// parser_validity invariant:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Initial state: insideConstrained may be true (with valid currentConstrained by precondition)
//   or false (with currentConstrained == [] by precondition).
//
//   After OpenConstrainedSpan (when !insideConstrainedOut):
//   currentConstrainedOut := [], insideConstrainedOut := true.
//   parser.IsValidPrefix([]) holds by precondition. ✓
//
//   After CloseSpanWithinBudget: postcondition guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//   (when insideConstrainedOut=false: vacuously true; 
//    when insideConstrainedOut=true: parser.IsValidPrefix(currentConstrainedOut) guaranteed). ✓
//
// progress invariant:
//   |generated| <= |generatedPrefix| + steps, cost <= maxSteps
//
//   OpenConstrainedSpan: appends "<<" (1 token), steps := 1.
//   |generated| = |generatedPrefix| + 1 = |generatedPrefix| + steps. ✓
//
//   CloseSpanWithinBudget with budget = min(closeBudget, remaining):
//   Postcondition: |generatedOut| <= |generated_before| + budget.
//   We set steps := maxSteps after, so:
//   |generated| <= |generatedPrefix| + 1 + budget <= |generatedPrefix| + 1 + (maxSteps - 1)
//              = |generatedPrefix| + maxSteps. ✓
//
//   cost := steps = maxSteps, satisfying cost <= maxSteps. ✓
//
// last progress ensures (maxSteps > 0 => cost > 0 OR observable change):
//   If maxSteps > 0:
//     - If !insideConstrained initially: OpenConstrainedSpan sets steps := 1, so cost := maxSteps >= 1 > 0. ✓
//     - If insideConstrained initially: CloseSpanWithinBudget runs, steps := maxSteps > 0. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Generate a single valid acrylate SMILES string. Acrylates must contain vinyl ester group C=CC(=O)O-. Use diverse R-groups: ethyl (CC), propyl (CCC), butyl (CCCC), isopropyl (C(C)C), isobutyl (CC(C)C), tert-butyl (C(C)(C)C), 2-ethylhexyl (CCCCC(CC)C), hydroxyethyl (CCO), methoxyethyl (CCOC), cyclohexyl (C1CCCCC1), benzyl (Cc1ccccc1), phenyl (c1ccccc1), furfuryl (Cc1ccco1), glycidyl (CC1CO1), dimethylaminoethyl (CCN(C)C), tetrahydrofurfuryl (CC1CCCO1). Examples: C=CC(=O)OCCC, C=CC(=O)OC(C)C, C=CC(=O)OCCCC, C=CC(=O)OCC(CC)CCCC, C=CC(=O)OCCO, C=CC(=O)OCCOC, C=CC(=O)OCC1CO1, C=CC(=O)OC1CCCCC1, C=CC(=O)OCc1ccccc1. Output ONLY the SMILES with no extra text.");

var steps: nat := 0;

