  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Use CloseSpanWithinBudget with budget=55 to:
// 1. Give enough tokens for complex acrylates (aromatic, cyclic) to complete
// 2. Prevent runaway repetitive generation (which causes syntax failures at 300+ tokens)
// 3. The "last complete prefix" tracking finds the longest valid SMILES within budget
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget := if remaining < 55 then remaining else 55;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;
